using UnityEngine;

public class DemoUsage : MonoBehaviour
{
    private void Start()
    {
        // Get the ExampleInventory component on this GameObject.
        var inventory = GetComponent<ExampleInventory>();

        // Initialize the inventory with 20 slots.
        inventory.Initialize(20);

        // Add and count items.
        inventory.AddItem("sword", 2);
        Debug.Log("Swords: " + inventory.CountItem("sword"));
    }
}

if (inventory.AddItem("sword", 2))
{
    Debug.Log("Added 2 swords.");
}

if (inventory.RemoveItem("sword", 1))
{
    Debug.Log("Removed 1 sword.");
}

Debug.Log("Swords left: " + inventory.CountItem("sword"));

using UnityEngine;

public class InventoryEvents : MonoBehaviour
{
    private void OnEnable()
    {
        ExampleInventory.OnItemAdded += HandleItemAdded;
        ExampleInventory.OnItemRemoved += HandleItemRemoved;
    }

    private void OnDisable()
    {
        ExampleInventory.OnItemAdded -= HandleItemAdded;
        ExampleInventory.OnItemRemoved -= HandleItemRemoved;
    }

    private void HandleItemAdded(string itemId, int amount)
    {
        Debug.Log("Added " + amount + "x " + itemId + ".");
    }

    private void HandleItemRemoved(string itemId, int amount)
    {
        Debug.Log("Removed " + amount + "x " + itemId + ".");
    }
}
